-- Shauager 22 (شواغر 22) - Database Schema Script
-- Designed for PostgreSQL 15 / Supabase

-- 1. STUDENT DETAILS / PROFILES EXTENSION
create table if not exists public.shauager_student_details (
    customer_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,
    full_name text not null,
    phone text not null,
    email text not null,
    major text not null check (major in ('ميكانيكا', 'تصنيع', 'مدنية', 'كهربا')),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

-- 2. OTP VERIFICATION CODES
create table if not exists public.shauager_otp_verifications (
    id uuid primary key default gen_random_uuid(),
    email text not null,
    code text not null,
    is_verified boolean not null default false,
    expires_at timestamptz not null,
    created_at timestamptz not null default now()
);

-- 3. POSTS TABLE
create table if not exists public.shauager_posts (
    id uuid primary key default gen_random_uuid(),
    title text not null,
    content text not null,
    post_type text not null check (post_type in ('جدول', 'محاضرات', 'فعاليات', 'أخبار')),
    target_major text not null check (target_major in ('الكل', 'ميكانيكا', 'تصنيع', 'مدنية', 'كهربا')),
    author_id uuid references auth.users(id) on delete set null,
    count_like integer not null default 0,
    count_love integer not null default 0,
    count_laugh integer not null default 0,
    count_wow integer not null default 0,
    count_sad integer not null default 0,
    count_pray integer not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

-- 4. POST ATTACHMENTS
create table if not exists public.shauager_attachments (
    id uuid primary key default gen_random_uuid(),
    post_id uuid not null references public.shauager_posts(id) on delete cascade,
    file_name text not null,
    file_url text not null,
    file_type text not null check (file_type in ('pdf', 'doc', 'image', 'video', 'other')),
    file_size_bytes bigint not null default 0,
    description text,
    created_at timestamptz not null default now()
);

-- 5. POST REACTIONS (EMOJIS ONLY)
create table if not exists public.shauager_reactions (
    id uuid primary key default gen_random_uuid(),
    post_id uuid not null references public.shauager_posts(id) on delete cascade,
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    emoji text not null check (emoji in ('👍', '❤️', '😂', '😮', '😢', '🙏')),
    created_at timestamptz not null default now(),
    constraint shauager_reactions_post_customer_unique unique (post_id, customer_id)
);

-- 6. STUDENT DOWNLOADS (OFFLINE TRACKING)
create table if not exists public.shauager_downloads (
    id uuid primary key default gen_random_uuid(),
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    attachment_id uuid not null references public.shauager_attachments(id) on delete cascade,
    post_id uuid not null references public.shauager_posts(id) on delete cascade,
    local_path text,
    created_at timestamptz not null default now(),
    constraint shauager_downloads_customer_attachment_unique unique (customer_id, attachment_id)
);

-- FUNCTION & TRIGGER FOR ATOMIC EMOJI COUNTS
create or replace function public.shauager_sync_reaction_counts()
returns trigger as $$
declare
    target_post_id uuid;
begin
    if (TG_OP = 'DELETE') then
        target_post_id := OLD.post_id;
    else
        target_post_id := NEW.post_id;
    end if;

    update public.shauager_posts
    set
        count_like  = (select count(*) from public.shauager_reactions where post_id = target_post_id and emoji = '👍'),
        count_love  = (select count(*) from public.shauager_reactions where post_id = target_post_id and emoji = '❤️'),
        count_laugh = (select count(*) from public.shauager_reactions where post_id = target_post_id and emoji = '😂'),
        count_wow   = (select count(*) from public.shauager_reactions where post_id = target_post_id and emoji = '😮'),
        count_sad   = (select count(*) from public.shauager_reactions where post_id = target_post_id and emoji = '😢'),
        count_pray  = (select count(*) from public.shauager_reactions where post_id = target_post_id and emoji = '🙏'),
        updated_at  = now()
    where id = target_post_id;

    return null;
end;
$$ language plpgsql security definer;

drop trigger if exists trigger_shauager_reaction_count_update on public.shauager_reactions;
create trigger trigger_shauager_reaction_count_update
after insert or update or delete on public.shauager_reactions
for each row execute function public.shauager_sync_reaction_counts();

-- ENABLE ROW LEVEL SECURITY
alter table public.shauager_student_details enable row level security;
alter table public.shauager_otp_verifications enable row level security;
alter table public.shauager_posts enable row level security;
alter table public.shauager_attachments enable row level security;
alter table public.shauager_reactions enable row level security;
alter table public.shauager_downloads enable row level security;

-- ROW LEVEL SECURITY POLICIES

-- shauager_student_details Policies
drop policy if exists "Students can read their own details" on public.shauager_student_details;
create policy "Students can read their own details"
on public.shauager_student_details for select to authenticated
using (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Students can insert their own details" on public.shauager_student_details;
create policy "Students can insert their own details"
on public.shauager_student_details for insert to authenticated
with check (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Students can update their own details" on public.shauager_student_details;
create policy "Students can update their own details"
on public.shauager_student_details for update to authenticated
using (customer_id = auth.uid() or public.shauager_is_admin())
with check (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Admins can manage student details" on public.shauager_student_details;
create policy "Admins can manage student details"
on public.shauager_student_details for all to authenticated
using (public.shauager_is_admin());

-- shauager_otp_verifications Policies
drop policy if exists "Users can access OTPs" on public.shauager_otp_verifications;
create policy "Users can access OTPs"
on public.shauager_otp_verifications for all to authenticated
using (true)
with check (true);

-- shauager_posts Policies
drop policy if exists "Authenticated users can view posts" on public.shauager_posts;
create policy "Authenticated users can view posts"
on public.shauager_posts for select to authenticated
using (true);

drop policy if exists "Admins can create posts" on public.shauager_posts;
create policy "Admins can create posts"
on public.shauager_posts for insert to authenticated
with check (public.shauager_is_admin());

drop policy if exists "Admins can update posts" on public.shauager_posts;
create policy "Admins can update posts"
on public.shauager_posts for update to authenticated
using (public.shauager_is_admin())
with check (public.shauager_is_admin());

drop policy if exists "Admins can delete posts" on public.shauager_posts;
create policy "Admins can delete posts"
on public.shauager_posts for delete to authenticated
using (public.shauager_is_admin());

-- shauager_attachments Policies
drop policy if exists "Authenticated users can view attachments" on public.shauager_attachments;
create policy "Authenticated users can view attachments"
on public.shauager_attachments for select to authenticated
using (true);

drop policy if exists "Admins can manage attachments" on public.shauager_attachments;
create policy "Admins can manage attachments"
on public.shauager_attachments for all to authenticated
using (public.shauager_is_admin())
with check (public.shauager_is_admin());

-- shauager_reactions Policies
drop policy if exists "Authenticated users can view reactions" on public.shauager_reactions;
create policy "Authenticated users can view reactions"
on public.shauager_reactions for select to authenticated
using (true);

drop policy if exists "Students can react to posts" on public.shauager_reactions;
create policy "Students can react to posts"
on public.shauager_reactions for insert to authenticated
with check (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Students can change their reactions" on public.shauager_reactions;
create policy "Students can change their reactions"
on public.shauager_reactions for update to authenticated
using (customer_id = auth.uid() or public.shauager_is_admin())
with check (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Students can remove their reactions" on public.shauager_reactions;
create policy "Students can remove their reactions"
on public.shauager_reactions for delete to authenticated
using (customer_id = auth.uid() or public.shauager_is_admin());

-- shauager_downloads Policies
drop policy if exists "Students can view their own downloads" on public.shauager_downloads;
create policy "Students can view their own downloads"
on public.shauager_downloads for select to authenticated
using (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Students can add to downloads" on public.shauager_downloads;
create policy "Students can add to downloads"
on public.shauager_downloads for insert to authenticated
with check (customer_id = auth.uid() or public.shauager_is_admin());

drop policy if exists "Students can delete their downloads record" on public.shauager_downloads;
create policy "Students can delete their downloads record"
on public.shauager_downloads for delete to authenticated
using (customer_id = auth.uid() or public.shauager_is_admin());

